{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Menaquinone-4, a polyprenyl quinone with the closest structural similarity to the query (Morgan 0.6591), had an absolute oral bioavailability of only 13.5% in dogs after soft-capsule dosing, directly supporting F < 20% for this polyprenyl quinone class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "MitoQ, which shares the same dimethoxybenzoquinone head and a long lipophilic alkyl chain as the query, has an oral availability of 10%, supporting low oral bioavailability for CoQ10-like quinones.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, a polar chromanol with a long isoprenoid tail, has poor oral bioavailability in humans, supporting low F for the analogous polar-head/long-lipophilic-tail architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lycopene, a large C40 polyisoprenoid, showed only about 1.2% systemic availability after oral dosing in humans, supporting low F for very large, highly lipophilic polyisoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a C40 polyisoprenoid hydrocarbon, showed 58.5% absolute bioavailability in humans, a counterexample showing that high lipophilicity alone does not always cause low F; however, its lack of a polar quinone head and lower molecular weight limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a prenylated polyphenol, has high oral bioavailability, but its much smaller size and different head group make it a weak counterexample for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is coenzyme Q10, a very large polyprenyl quinone. The closest structural analogues—menaquinone-4 (absolute F 13.5% in dogs) and MitoQ (10% oral availability)—both fall below 20%, and tocotrienol and lycopene also show poor oral bioavailability. The main counterexamples (phytoene, hyperforin, and high-F small-molecule drugs) are structurally distant or lack the polar quinone head, so they do not outweigh the direct polyprenyl quinone evidence. Therefore F < 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for coenzyme Q10 itself in the provided evidence.",
    "Menaquinone-4 data are from dogs, and species differences in absorption and efflux may affect translation to humans.",
    "Formulation, food effects, and dose form can markedly alter the absorption of highly lipophilic quinones.",
    "Carotenoid bioavailability is highly variable (e.g., phytoene high vs lycopene low), creating some uncertainty in which analogue best represents CoQ10."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C37", "C35", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "menaquinone-4"
    },
    {
      "applicability": "high",
      "card_ids": ["C27"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "MitoQ"
    },
    {
      "applicability": "low",
      "card_ids": ["C31", "C38"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "salirasib"
    },
    {
      "applicability": "low",
      "card_ids": ["C33", "C28", "C34", "C30", "C36"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "mycophenolate mofetil/MPA"
    },
    {
      "applicability": "low",
      "card_ids": ["C32"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "fusidic acid"
    }
  ],
  "revision_action": "strengthen"
}

